#[cfg(test)]
mod relay_channel_observation_tests {
    use super::*;
    use std::io::{self, Read};

    const GUARD: Duration = Duration::from_secs(10);

    struct OwnedChild(Child);

    impl Drop for OwnedChild {
        fn drop(&mut self) {
            let _ = self.0.kill();
            let _ = self.0.wait();
        }
    }

    struct InputDropGate<R> {
        input: Option<R>,
        dropped: SyncSender<()>,
        release: Receiver<()>,
    }

    impl<R: Read> Read for InputDropGate<R> {
        fn read(&mut self, bytes: &mut [u8]) -> io::Result<usize> {
            self.input.as_mut().unwrap().read(bytes)
        }
    }

    impl<R> Drop for InputDropGate<R> {
        fn drop(&mut self) {
            drop(self.input.take());
            let _ = self.dropped.try_send(());
            let _ = self.release.recv_timeout(GUARD);
        }
    }

    #[test]
    fn real_pipe_eof_drops_the_sender_before_notification_without_consuming_the_line() {
        let record = SessionLine::Pong { seq: 7, lamp_us: 9 };
        let script = format!(
            "printf '%s\n' '{}'; IFS= read -r command || exit 0",
            serde_json::to_string(&record).unwrap()
        );
        let mut child = OwnedChild(
            Command::new("/bin/sh")
                .args(["-c", &script])
                .stdin(Stdio::piped())
                .stdout(Stdio::piped())
                .spawn()
                .unwrap(),
        );
        let (dropped, input_dropped) = mpsc::sync_channel(1);
        let (release, proceed) = mpsc::sync_channel(1);
        let (closed, notice) = mpsc::sync_channel(1);
        let enqueued = Arc::new(AtomicU64::new(0));
        let lines = relay_reader_with_progress_capacity_observed(
            InputDropGate {
                input: child.0.stdout.take(),
                dropped,
                release: proceed,
            },
            Some(enqueued.clone()),
            1,
            Some(closed),
        );
        let deadline = Instant::now() + GUARD;
        while enqueued.load(Ordering::Acquire) != 1 {
            assert!(Instant::now() < deadline, "real pipe frame was not queued");
            thread::sleep(Duration::from_millis(1));
        }
        assert_eq!(notice.try_recv(), Err(TryRecvError::Empty));
        drop(child.0.stdin.take());
        input_dropped.recv_timeout(GUARD).unwrap();
        // The OS input has really dropped, but the framer's destructor is
        // still parked and the line channel's producer is still alive.
        assert_eq!(notice.try_recv(), Err(TryRecvError::Empty));
        release.send(()).unwrap();
        notice.recv_timeout(GUARD).unwrap();
        assert_eq!(enqueued.load(Ordering::Acquire), 1);
        assert_eq!(lines.try_recv(), Ok(Ok(record)));
        assert_eq!(lines.try_recv(), Err(TryRecvError::Disconnected));
        assert_eq!(notice.try_recv(), Err(TryRecvError::Disconnected));
        // OwnedChild cleanup remains separate from the sender-drop receipt.
    }

    #[test]
    fn a_read_failure_closes_the_sender_but_retains_the_original_error() {
        struct FailedRead;
        impl Read for FailedRead {
            fn read(&mut self, _: &mut [u8]) -> io::Result<usize> {
                Err(io::Error::other("closure observation read failure"))
            }
        }
        let (closed, notice) = mpsc::sync_channel(1);
        let enqueued = Arc::new(AtomicU64::new(0));
        let lines = relay_reader_with_progress_capacity_observed(
            FailedRead,
            Some(enqueued.clone()),
            1,
            Some(closed),
        );
        notice.recv_timeout(GUARD).unwrap();
        assert_eq!(enqueued.load(Ordering::Acquire), 0);
        assert_eq!(
            lines.try_recv(),
            Ok(Err("relay transport read failed: closure observation read failure".into()))
        );
        assert_eq!(lines.try_recv(), Err(TryRecvError::Disconnected));
    }
}
